<?php

declare(strict_types=1);

namespace BohnMedia\MediaCodecs\Tests;

use BohnMedia\MediaCodecs\MediaType;
use BohnMedia\MediaCodecs\MediaTypeDetector;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

class MediaTypeDetectorTest extends TestCase
{
    /**
     * The fixtures are generated by tests/Fixtures/generate.sh (ffmpeg); the expected strings follow RFC 6381 and the
     * codec registrations at https://mp4ra.org and https://www.matroska.org/technical/codec_specs.html
     */
    #[DataProvider('getFixtures')]
    public function testDetectsTheMediaType(string $file, string|null $expected): void
    {
        $mediaType = (new MediaTypeDetector())->detectFromFile(__DIR__.'/Fixtures/'.$file);

        $this->assertSame($expected, null === $mediaType ? null : (string) $mediaType);
    }

    /**
     * @return iterable<string, array{0: string, 1: string|null}>
     */
    public static function getFixtures(): iterable
    {
        yield 'AV1 + AAC in MP4' => ['av1-aac.mp4', 'video/mp4; codecs="av01.0.00M.08, mp4a.40.2"'];
        yield 'AV1 10 bit' => ['av1-10bit.mp4', 'video/mp4; codecs="av01.0.00M.10"'];
        yield 'HEVC hvc1 + AAC' => ['hevc-hvc1-aac.mp4', 'video/mp4; codecs="hvc1.1.6.L90.90, mp4a.40.2"'];
        yield 'HEVC hev1' => ['hevc-hev1.mp4', 'video/mp4; codecs="hev1.1.6.L90.90"'];
        yield 'H.264 High 3.1 + AAC' => ['h264-aac.mp4', 'video/mp4; codecs="avc1.64001F, mp4a.40.2"'];
        yield 'H.264 with moov first (faststart)' => ['h264-faststart.mp4', 'video/mp4; codecs="avc1.64000A"'];
        yield 'H.264 Baseline in QuickTime' => ['h264-baseline.mov', 'video/quicktime; codecs="avc1.42C01E"'];
        yield 'H.264 + AAC in QuickTime (esds in wave box)' => ['h264-aac.mov', 'video/quicktime; codecs="avc1.42C01E, mp4a.40.2"'];
        yield 'unknown video codec: no codecs parameter' => ['mpeg4-aac.mp4', 'video/mp4'];
        yield 'VP9 + Opus in WebM' => ['vp9-opus.webm', 'video/webm; codecs="vp9, opus"'];
        yield 'AV1 in WebM' => ['av1.webm', 'video/webm; codecs="av01.0.00M.08"'];
        yield 'VP8 + Vorbis in WebM' => ['vp8-vorbis.webm', 'video/webm; codecs="vp8, vorbis"'];
        yield 'AAC in M4A' => ['aac.m4a', 'audio/mp4; codecs="mp4a.40.2"'];
        yield 'Opus in WebM (audio only)' => ['opus.webm', 'audio/webm; codecs="opus"'];
        yield 'H.264 + AAC in Matroska' => ['h264-aac.mkv', 'video/x-matroska; codecs="avc1.64000A, mp4a.40.2"'];
        yield 'VP9 + AC-3 in Matroska' => ['vp9-ac3.mkv', 'video/x-matroska; codecs="vp9, ac-3"'];
        yield 'not a media file' => ['plain.txt', null];
    }

    public function testReturnsNullForMissingFilesAndUnseekableStreams(): void
    {
        $detector = new MediaTypeDetector();

        $this->assertNull($detector->detectFromFile(__DIR__.'/Fixtures/does-not-exist.mp4'));

        $stream = fopen('php://output', 'r'); // not seekable
        $this->assertNotFalse($stream);
        $this->assertNull($detector->detectFromStream($stream));
    }

    public function testExposesEssenceAndCodecsSeparately(): void
    {
        $mediaType = (new MediaTypeDetector())->detectFromFile(__DIR__.'/Fixtures/av1-aac.mp4');

        $this->assertInstanceOf(MediaType::class, $mediaType);
        $this->assertSame('video/mp4', $mediaType->getEssence());
        $this->assertSame(['av01.0.00M.08', 'mp4a.40.2'], $mediaType->getCodecs());
        $this->assertTrue($mediaType->hasCodecs());
        $this->assertSame('video/webm', (string) new MediaType('video/webm'));
    }
}
